mapper.select:
SELECT 
  FROM alphafrog_agent_run_child_intent i
  JOIN alphafrog_agent_run_child_outbox o ON o.intent_id = i.id
 WHERE i.parent_wait_group_id = #{request.parentWaitGroupId}
   AND i.parent_member_identity = #{request.parentMemberIdentity}

SELECT count(*) FROM alphafrog_agent_run_wait_group g
JOIN alphafrog_agent_run_wait_member m ON m.group_id = g.id AND m.run_id = g.run_id
WHERE g.id = #{request.parentWaitGroupId}
  AND g.run_id = #{request.parentRunId}
  AND g.plan_generation = #{request.planGeneration}
  AND g.node_id = #{request.parentNodeId}
  AND g.node_attempt = #{request.nodeAttempt}
  AND g.state = 'WAITING'
  AND m.member_identity = #{request.parentMemberIdentity}
  AND m.tool_call_id = #{request.toolCallId}
  AND m.tool_name = 'spawnSubAgent'

mapper.update:
UPDATE alphafrog_agent_run_tree_capacity
   SET active_child_count = active_child_count + 1, updated_at = CURRENT_TIMESTAMP
 WHERE root_run_id = #{rootRunId} AND active_child_count < #{limit}

mapper.select:
SELECT root_run_id FROM alphafrog_agent_run_tree_capacity
WHERE active_child_count > 0

    AND root_run_id > #{afterRootRunId}

ORDER BY root_run_id LIMIT #{limit}

SELECT , child.status AS child_run_status
  FROM alphafrog_agent_run_child_intent i
  JOIN alphafrog_agent_run_child_outbox o ON o.intent_id = i.id
  LEFT JOIN alphafrog_agent_run child ON child.id = i.child_run_id
 WHERE i.parent_run_id = #{parentRunId}
   AND i.id > #{afterIntentId}
   AND i.capacity_released_at IS NULL
 ORDER BY i.id LIMIT #{limit}

SELECT , child.status AS child_run_status
  FROM alphafrog_agent_run_child_intent i
  JOIN alphafrog_agent_run_child_outbox o ON o.intent_id = i.id
  LEFT JOIN alphafrog_agent_run child ON child.id = i.child_run_id
 WHERE i.root_run_id = #{rootRunId}
   AND i.id > #{afterIntentId}
   AND i.capacity_released_at IS NULL
 ORDER BY i.id LIMIT #{limit}
